/* CABECERA Y MENU */ /* Combo del pais (cab1) */
	/*En estos momentos este combo no aparece*/
.cab1 {
	font-family: Verdana, Arial, Helvetica, sans-serif;
	font-size: 10px;
	margin-top: 30px;
}

/* Combo de Acceso rapido (cab2) */
.cab2 {
	font-family: Verdana, Arial, Helvetica, sans-serif;
	font-size: 10px;
}

/* Texto de "Elija operacion a realizar" (cab3) */
.cab3 {
	font-family: Verdana, Arial, Helvetica, sans-serif;
	font-size: 11px;
	color: #FFFFFF;
	text-decoration: none;
	text-indent: 3px;
	background-color: #FF0000;
}

/* Opciones del menu (cab4) */
.cab4 {
	font-family: Verdana, Arial, Helvetica, sans-serif;
	font-size: 11px;
	color: #FFFFFF;
	font-weight: bold;
	text-decoration: none;
	background-color: #FF0000;
}

.cab4 A {
	color: #FFFFFF;
	text-decoration: none;
	background-color: #FF0000;
}

.cab4 A:hover {
	color: #FFFFFF;
	text-decoration: underline;
	background-color: #FF0000;
}

/* Datos del usuario (cab5) */
.cab5 {
	font-family: Verdana, Arial, Helvetica, sans-serif;
	font-size: 10px;
	color: #000000;
	font-weight: normal;
	text-decoration: none;
}

