.cab6 {
	font-family: Verdana, Arial, Helvetica, sans-serif;
	font-size: 11px;
	color: #000000;
	font-weight: bold;
	text-decoration: none;
}

.cab6 A {
	color: #000000;
	text-decoration: none;
}

/* Logado de usuario*/
.cab7 {
	font-family: Tahoma, Verdana, Arial, Helvetica, sans-serif;
	font-size: 11px;
	color: #000000;
	font-weight: bold;
	text-decoration: none;
}

.cab8 {
	font-family: Tahoma, Arial, Helvetica, Verdana;
	font-size: 11px;
	color: #000000;
	font-weight: bold;
	text-decoration: none;
}

/*Panel de control*/
.cab9 {
	font-family: Tahoma, Arial, Helvetica, Verdana;
